110	pub fn memory_results(matches: &[ax_memory::MemoryMatch]) -> String {
111	    let mut text =
112	        String::from("## Relevant memories\n\nUse `ax_recall` with `id` for full content.\n");
113	    for m in matches {
114	        let summary: String = m.memory.body.chars().take(240).collect();
115	        text.push_str(&format!(
116	            "\n- {} [{}] {} — {}{}\n",
117	            m.memory.id,
118	            m.memory.kind,
119	            m.memory.title.replace('\n', " "),
120	            summary.replace('\n', " "),
121	            if m.memory.body.chars().count() > 240 {
122	                "… (full content available by ID)"
123	            } else {
124	                ""
125	            }
126	        ));
127	        if !m.memory.files.is_empty() {
128	            text.push_str(&format!("  Files: {}\n", m.memory.files.join(", ")));
129	        }
130	    }
131	    text
132	}

134	pub fn recall_metadata(value: &Value) -> Value {
135	    let entries: Vec<Value> = value.get("matches").and_then(Value::as_array).into_iter().flatten().map(|entry| {
136	        let memory = &entry["memory"];
137	        let mut meta = json!({"id":memory.get("id"),"kind":memory.get("kind"),"score":entry.get("score"),"files":memory.get("files"),"source":memory.get("source")});
138	        if let Some(obj) = meta.as_object_mut() { obj.retain(|_, v| !v.is_null()); }
139	        meta
140	    }).collect();
141	    json!({"matches":entries})
142	}
